using System.Text.Json;
using Dapper;
using Sigov.Application.Agro.Programas;
using Sigov.Application.Common;
using Sigov.Infrastructure.Persistence.Dapper;

namespace Sigov.Infrastructure.Agro.Repositories;

public sealed class AgroProgramasRepository : IAgroProgramasRepository
{
    private readonly DapperContext _context; public AgroProgramasRepository(DapperContext context)=>_context=context;
    public async Task<PagedResult<AgroProgramaRuralResponse>> ListarProgramasAsync(long tenantId,long entidadeId,AgroProgramaRuralFiltro f,CancellationToken ct){const string data="select id,tenant_id TenantId,entidade_id EntidadeId,codigo,nome,tipo_programa TipoPrograma,descricao,vigencia_inicio VigenciaInicio,vigencia_fim VigenciaFim,ativo from sigov.agro_programa_rural where tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false and (@Ativo is null or ativo=@Ativo) and (@Tipo is null or tipo_programa=@Tipo) and (@Busca is null or codigo ilike @Busca or nome ilike @Busca) order by nome limit @Limit offset @Offset"; const string count="select count(*) from sigov.agro_programa_rural where tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false and (@Ativo is null or ativo=@Ativo) and (@Tipo is null or tipo_programa=@Tipo) and (@Busca is null or codigo ilike @Busca or nome ilike @Busca)"; return await Page<AgroProgramaRuralResponse>(data,count,tenantId,entidadeId,f,ct);}
    public async Task<AgroProgramaRuralResponse?> ObterProgramaAsync(long tenantId,long entidadeId,long id,CancellationToken ct){const string sql="select id,tenant_id TenantId,entidade_id EntidadeId,codigo,nome,tipo_programa TipoPrograma,descricao,vigencia_inicio VigenciaInicio,vigencia_fim VigenciaFim,ativo from sigov.agro_programa_rural where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false"; using var cn=_context.CreateConnection(); return await cn.QuerySingleOrDefaultAsync<AgroProgramaRuralResponse>(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,Id=id},cancellationToken:ct));}
    public async Task<long> CriarProgramaAsync(long tenantId,long entidadeId,long? usuarioId,AgroProgramaRuralCreateRequest r,CancellationToken ct){const string sql="insert into sigov.agro_programa_rural(tenant_id,entidade_id,codigo,nome,tipo_programa,descricao,criterios_json,vigencia_inicio,vigencia_fim,ativo,created_by,correlation_id) values(@TenantId,@EntidadeId,@Codigo,@Nome,@TipoPrograma,@Descricao,cast(@CriteriosJson as jsonb),@VigenciaInicio,@VigenciaFim,@Ativo,@UsuarioId,@CorrelationId) returning id"; using var cn=_context.CreateConnection(); var id=await cn.ExecuteScalarAsync<long>(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,r.Codigo,r.Nome,r.TipoPrograma,r.Descricao,CriteriosJson=Json(r.CriteriosJson),r.VigenciaInicio,r.VigenciaFim,r.Ativo,UsuarioId=usuarioId,CorrelationId=Guid.NewGuid()},cancellationToken:ct)); await Evento(cn,tenantId,entidadeId,null,usuarioId,"AgroProgramaRuralCriado","agro_programa_rural",id,ct); return id;}
    public async Task AtualizarProgramaAsync(long tenantId,long entidadeId,long id,long? usuarioId,AgroProgramaRuralUpdateRequest r,CancellationToken ct){const string sql="update sigov.agro_programa_rural set codigo=@Codigo,nome=@Nome,tipo_programa=@TipoPrograma,descricao=@Descricao,criterios_json=cast(@CriteriosJson as jsonb),vigencia_inicio=@VigenciaInicio,vigencia_fim=@VigenciaFim,ativo=@Ativo,updated_at=now(),updated_by=@UsuarioId where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,Id=id,r.Codigo,r.Nome,r.TipoPrograma,r.Descricao,CriteriosJson=Json(r.CriteriosJson),r.VigenciaInicio,r.VigenciaFim,r.Ativo,UsuarioId=usuarioId},cancellationToken:ct));}
    public async Task ExcluirProgramaAsync(long tenantId,long entidadeId,long id,long? usuarioId,CancellationToken ct)=>await Soft("sigov.agro_programa_rural",tenantId,entidadeId,id,usuarioId,ct);
    public async Task<PagedResult<AgroBeneficioRuralResponse>> ListarBeneficiosAsync(long tenantId,long entidadeId,AgroProgramaRuralFiltro f,CancellationToken ct){const string data="select id,tenant_id TenantId,entidade_id EntidadeId,programa_id ProgramaId,codigo,nome,tipo_beneficio TipoBeneficio,unidade_medida UnidadeMedida,valor_referencia ValorReferencia,quantidade_limite QuantidadeLimite,ativo from sigov.agro_beneficio_rural where tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false and (@Ativo is null or ativo=@Ativo) and (@Busca is null or codigo ilike @Busca or nome ilike @Busca) order by nome limit @Limit offset @Offset"; const string count="select count(*) from sigov.agro_beneficio_rural where tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false and (@Ativo is null or ativo=@Ativo) and (@Busca is null or codigo ilike @Busca or nome ilike @Busca)"; return await Page<AgroBeneficioRuralResponse>(data,count,tenantId,entidadeId,f,ct);}
    public async Task<AgroBeneficioRuralResponse?> ObterBeneficioAsync(long tenantId,long entidadeId,long id,CancellationToken ct){const string sql="select id,tenant_id TenantId,entidade_id EntidadeId,programa_id ProgramaId,codigo,nome,tipo_beneficio TipoBeneficio,unidade_medida UnidadeMedida,valor_referencia ValorReferencia,quantidade_limite QuantidadeLimite,ativo from sigov.agro_beneficio_rural where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false"; using var cn=_context.CreateConnection(); return await cn.QuerySingleOrDefaultAsync<AgroBeneficioRuralResponse>(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,Id=id},cancellationToken:ct));}
    public async Task<long> CriarBeneficioAsync(long tenantId,long entidadeId,long? usuarioId,AgroBeneficioRuralCreateRequest r,CancellationToken ct){const string sql="insert into sigov.agro_beneficio_rural(tenant_id,entidade_id,programa_id,codigo,nome,tipo_beneficio,unidade_medida,valor_referencia,quantidade_limite,criterios_json,ativo,created_by,correlation_id) values(@TenantId,@EntidadeId,@ProgramaId,@Codigo,@Nome,@TipoBeneficio,@UnidadeMedida,@ValorReferencia,@QuantidadeLimite,cast(@CriteriosJson as jsonb),@Ativo,@UsuarioId,@CorrelationId) returning id"; using var cn=_context.CreateConnection(); var id=await cn.ExecuteScalarAsync<long>(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,r.ProgramaId,r.Codigo,r.Nome,r.TipoBeneficio,r.UnidadeMedida,r.ValorReferencia,r.QuantidadeLimite,CriteriosJson=Json(r.CriteriosJson),r.Ativo,UsuarioId=usuarioId,CorrelationId=Guid.NewGuid()},cancellationToken:ct)); await Evento(cn,tenantId,entidadeId,null,usuarioId,"AgroBeneficioRuralCriado","agro_beneficio_rural",id,ct); return id;}
    public async Task AtualizarBeneficioAsync(long tenantId,long entidadeId,long id,long? usuarioId,AgroBeneficioRuralUpdateRequest r,CancellationToken ct){const string sql="update sigov.agro_beneficio_rural set programa_id=@ProgramaId,codigo=@Codigo,nome=@Nome,tipo_beneficio=@TipoBeneficio,unidade_medida=@UnidadeMedida,valor_referencia=@ValorReferencia,quantidade_limite=@QuantidadeLimite,criterios_json=cast(@CriteriosJson as jsonb),ativo=@Ativo,updated_at=now(),updated_by=@UsuarioId where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,Id=id,r.ProgramaId,r.Codigo,r.Nome,r.TipoBeneficio,r.UnidadeMedida,r.ValorReferencia,r.QuantidadeLimite,CriteriosJson=Json(r.CriteriosJson),r.Ativo,UsuarioId=usuarioId},cancellationToken:ct));}
    public async Task ExcluirBeneficioAsync(long tenantId,long entidadeId,long id,long? usuarioId,CancellationToken ct)=>await Soft("sigov.agro_beneficio_rural",tenantId,entidadeId,id,usuarioId,ct);
    public async Task<PagedResult<AgroBeneficioConcessaoResponse>> ListarConcessoesAsync(long tenantId,long entidadeId,AgroBeneficioConcessaoFiltro f,CancellationToken ct){const string data="select c.id,c.tenant_id TenantId,c.entidade_id EntidadeId,c.exercicio_id ExercicioId,c.beneficio_id BeneficioId,c.produtor_id ProdutorId,c.propriedade_id PropriedadeId,c.numero,c.data_solicitacao DataSolicitacao,c.data_concessao DataConcessao,c.quantidade,c.valor,c.status,coalesce(left(p.nome,1)||'***','Produtor rural') ProdutorNomeMascarado,c.observacao from sigov.agro_beneficio_concessao c left join sigov.agro_produtor ap on ap.id=c.produtor_id and ap.tenant_id=c.tenant_id left join sigov.pessoa p on p.id=ap.pessoa_id where c.tenant_id=@TenantId and c.entidade_id=@EntidadeId and c.is_deleted=false and (@ProdutorId is null or c.produtor_id=@ProdutorId) and (@Status is null or c.status=@Status) order by c.created_at desc limit @Limit offset @Offset"; const string count="select count(*) from sigov.agro_beneficio_concessao c where c.tenant_id=@TenantId and c.entidade_id=@EntidadeId and c.is_deleted=false and (@ProdutorId is null or c.produtor_id=@ProdutorId) and (@Status is null or c.status=@Status)"; using var cn=_context.CreateConnection(); var args=new{TenantId=tenantId,EntidadeId=entidadeId,f.ProdutorId,Status=Empty(f.Status),Limit=f.PageSize,Offset=(f.Page-1)*f.PageSize}; var items=(await cn.QueryAsync<AgroBeneficioConcessaoResponse>(new CommandDefinition(data,args,cancellationToken:ct))).ToArray(); var total=await cn.ExecuteScalarAsync<long>(new CommandDefinition(count,args,cancellationToken:ct)); return new(items,f.Page,f.PageSize,total);}
    public async Task<AgroBeneficioConcessaoResponse?> ObterConcessaoAsync(long tenantId,long entidadeId,long id,CancellationToken ct){const string sql="select c.id,c.tenant_id TenantId,c.entidade_id EntidadeId,c.exercicio_id ExercicioId,c.beneficio_id BeneficioId,c.produtor_id ProdutorId,c.propriedade_id PropriedadeId,c.numero,c.data_solicitacao DataSolicitacao,c.data_concessao DataConcessao,c.quantidade,c.valor,c.status,coalesce(left(p.nome,1)||'***','Produtor rural') ProdutorNomeMascarado,c.observacao from sigov.agro_beneficio_concessao c left join sigov.agro_produtor ap on ap.id=c.produtor_id and ap.tenant_id=c.tenant_id left join sigov.pessoa p on p.id=ap.pessoa_id where c.tenant_id=@TenantId and c.entidade_id=@EntidadeId and c.id=@Id and c.is_deleted=false"; using var cn=_context.CreateConnection(); return await cn.QuerySingleOrDefaultAsync<AgroBeneficioConcessaoResponse>(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,Id=id},cancellationToken:ct));}
    public async Task<long> CriarConcessaoAsync(long tenantId,long entidadeId,long? exercicioId,long? usuarioId,AgroBeneficioConcessaoCreateRequest r,string numero,CancellationToken ct){const string sql="insert into sigov.agro_beneficio_concessao(tenant_id,entidade_id,exercicio_id,beneficio_id,produtor_id,propriedade_id,numero,quantidade,valor,status,observacao,created_by,correlation_id) values(@TenantId,@EntidadeId,@ExercicioId,@BeneficioId,@ProdutorId,@PropriedadeId,@Numero,@Quantidade,@Valor,'SOLICITADO',@Observacao,@UsuarioId,@CorrelationId) returning id"; using var cn=_context.CreateConnection(); var id=await cn.ExecuteScalarAsync<long>(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,ExercicioId=exercicioId,r.BeneficioId,r.ProdutorId,r.PropriedadeId,Numero=numero,r.Quantidade,r.Valor,r.Observacao,UsuarioId=usuarioId,CorrelationId=Guid.NewGuid()},cancellationToken:ct)); await Evento(cn,tenantId,entidadeId,exercicioId,usuarioId,"AgroBeneficioRuralSolicitado","agro_beneficio_concessao",id,ct); return id;}
    public async Task AtualizarStatusConcessaoAsync(long tenantId,long entidadeId,long id,long? usuarioId,string status,string? observacao,CancellationToken ct){const string sql="update sigov.agro_beneficio_concessao set status=@Status, observacao=coalesce(@Observacao,observacao), data_concessao=case when @Status in ('AUTORIZADO','CONCEDIDO') then current_date else data_concessao end, autorizado_by=case when @Status='AUTORIZADO' then @UsuarioId else autorizado_by end, autorizado_at=case when @Status='AUTORIZADO' then now() else autorizado_at end, entregue_by=case when @Status='ENTREGUE' then @UsuarioId else entregue_by end, entregue_at=case when @Status='ENTREGUE' then now() else entregue_at end, updated_at=now(),updated_by=@UsuarioId where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,Id=id,UsuarioId=usuarioId,Status=status,Observacao=observacao},cancellationToken:ct)); await Evento(cn,tenantId,entidadeId,null,usuarioId,$"AgroBeneficioRural{Title(status)}","agro_beneficio_concessao",id,ct);}
    public async Task<PagedResult<AgroInsumoResponse>> ListarInsumosAsync(long tenantId,long entidadeId,AgroProgramaRuralFiltro f,CancellationToken ct){const string data="select id,tenant_id TenantId,entidade_id EntidadeId,codigo,nome,tipo_insumo TipoInsumo,unidade_medida UnidadeMedida,controla_estoque ControlaEstoque,produto_id ProdutoId,ativo from sigov.agro_insumo where tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false and (@Busca is null or codigo ilike @Busca or nome ilike @Busca) order by nome limit @Limit offset @Offset"; const string count="select count(*) from sigov.agro_insumo where tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false and (@Busca is null or codigo ilike @Busca or nome ilike @Busca)"; return await Page<AgroInsumoResponse>(data,count,tenantId,entidadeId,f,ct);}
    public async Task<long> CriarInsumoAsync(long tenantId,long entidadeId,long? usuarioId,AgroInsumoCreateRequest r,CancellationToken ct){const string sql="insert into sigov.agro_insumo(tenant_id,entidade_id,codigo,nome,tipo_insumo,unidade_medida,controla_estoque,produto_id,ativo,created_by,correlation_id) values(@TenantId,@EntidadeId,@Codigo,@Nome,@TipoInsumo,@UnidadeMedida,@ControlaEstoque,@ProdutoId,@Ativo,@UsuarioId,@CorrelationId) returning id"; using var cn=_context.CreateConnection(); var id=await cn.ExecuteScalarAsync<long>(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,r.Codigo,r.Nome,r.TipoInsumo,r.UnidadeMedida,r.ControlaEstoque,r.ProdutoId,r.Ativo,UsuarioId=usuarioId,CorrelationId=Guid.NewGuid()},cancellationToken:ct)); await Evento(cn,tenantId,entidadeId,null,usuarioId,"AgroInsumoCriado","agro_insumo",id,ct); return id;}
    public async Task<PagedResult<AgroDistribuicaoInsumoResponse>> ListarDistribuicoesAsync(long tenantId,long entidadeId,AgroBeneficioConcessaoFiltro f,CancellationToken ct){const string data="select d.id,d.tenant_id TenantId,d.entidade_id EntidadeId,d.exercicio_id ExercicioId,d.insumo_id InsumoId,d.produtor_id ProdutorId,d.propriedade_id PropriedadeId,d.numero,d.data_distribuicao DataDistribuicao,d.quantidade,d.valor_estimado ValorEstimado,d.status,coalesce(left(p.nome,1)||'***','Produtor rural') ProdutorNomeMascarado from sigov.agro_distribuicao_insumo d left join sigov.agro_produtor ap on ap.id=d.produtor_id and ap.tenant_id=d.tenant_id left join sigov.pessoa p on p.id=ap.pessoa_id where d.tenant_id=@TenantId and d.entidade_id=@EntidadeId and d.is_deleted=false order by d.created_at desc limit @Limit offset @Offset"; const string count="select count(*) from sigov.agro_distribuicao_insumo where tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false"; using var cn=_context.CreateConnection(); var args=new{TenantId=tenantId,EntidadeId=entidadeId,Limit=f.PageSize,Offset=(f.Page-1)*f.PageSize}; var items=(await cn.QueryAsync<AgroDistribuicaoInsumoResponse>(new CommandDefinition(data,args,cancellationToken:ct))).ToArray(); var total=await cn.ExecuteScalarAsync<long>(new CommandDefinition(count,args,cancellationToken:ct)); return new(items,f.Page,f.PageSize,total);}
    public async Task<long> CriarDistribuicaoAsync(long tenantId,long entidadeId,long? exercicioId,long? usuarioId,AgroDistribuicaoInsumoCreateRequest r,string numero,CancellationToken ct){const string sql="insert into sigov.agro_distribuicao_insumo(tenant_id,entidade_id,exercicio_id,insumo_id,produtor_id,propriedade_id,programa_id,beneficio_concessao_id,numero,quantidade,valor_estimado,status,entregue_by,observacao,created_by,correlation_id) values(@TenantId,@EntidadeId,@ExercicioId,@InsumoId,@ProdutorId,@PropriedadeId,@ProgramaId,@BeneficioConcessaoId,@Numero,@Quantidade,@ValorEstimado,'ENTREGUE',@UsuarioId,@Observacao,@UsuarioId,@CorrelationId) returning id"; using var cn=_context.CreateConnection(); var id=await cn.ExecuteScalarAsync<long>(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,ExercicioId=exercicioId,r.InsumoId,r.ProdutorId,r.PropriedadeId,r.ProgramaId,r.BeneficioConcessaoId,Numero=numero,r.Quantidade,r.ValorEstimado,r.Observacao,UsuarioId=usuarioId,CorrelationId=Guid.NewGuid()},cancellationToken:ct)); await Evento(cn,tenantId,entidadeId,exercicioId,usuarioId,"AgroInsumoDistribuido","agro_distribuicao_insumo",id,ct); return id;}
    private async Task<PagedResult<T>> Page<T>(string data,string count,long tenantId,long entidadeId,AgroProgramaRuralFiltro f,CancellationToken ct){using var cn=_context.CreateConnection(); var args=new{TenantId=tenantId,EntidadeId=entidadeId,Ativo=f.Ativo,Tipo=Empty(f.TipoPrograma),Busca=string.IsNullOrWhiteSpace(f.Busca)?null:$"%{f.Busca}%",Limit=f.PageSize,Offset=(f.Page-1)*f.PageSize}; var items=(await cn.QueryAsync<T>(new CommandDefinition(data,args,cancellationToken:ct))).ToArray(); var total=await cn.ExecuteScalarAsync<long>(new CommandDefinition(count,args,cancellationToken:ct)); return new(items,f.Page,f.PageSize,total);}
    private async Task Soft(string table,long tenantId,long entidadeId,long id,long? usuarioId,CancellationToken ct){using var cn=_context.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition($"update {table} set is_deleted=true,ativo=false,deleted_at=now(),deleted_by=@UsuarioId where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false",new{TenantId=tenantId,EntidadeId=entidadeId,Id=id,UsuarioId=usuarioId},cancellationToken:ct));}
    private static string Json(string? json)=>string.IsNullOrWhiteSpace(json)?"{}":json!; private static string? Empty(string? v)=>string.IsNullOrWhiteSpace(v)?null:v; private static string Title(string s)=>string.Concat(s.ToLowerInvariant().Split('_').Select(x=>char.ToUpperInvariant(x[0])+x[1..]));
    private static async Task Evento(System.Data.IDbConnection cn,long tenantId,long entidadeId,long? exercicioId,long? usuarioId,string tipo,string origem,long origemId,CancellationToken ct)
    {
        await cn.ExecuteAsync(new CommandDefinition("insert into sigov.agro_evento(tenant_id,entidade_id,exercicio_id,tipo_evento,origem,origem_id,payload_json,created_by,correlation_id) values(@TenantId,@EntidadeId,@ExercicioId,@Tipo,@Origem,@OrigemId,cast(@Payload as jsonb),@UsuarioId,@CorrelationId)",new{TenantId=tenantId,EntidadeId=entidadeId,ExercicioId=exercicioId,Tipo=tipo,Origem=origem,OrigemId=origemId,Payload=JsonSerializer.Serialize(new{tenantId,entidadeId,exercicioId,origem,origemId,tipoEvento=tipo}),UsuarioId=usuarioId,CorrelationId=Guid.NewGuid()},cancellationToken:ct)).ConfigureAwait(false);
    }
}
